ALTER TABLE "report_scores" DROP CONSTRAINT "rs_gate_completeness";--> statement-breakpoint
ALTER TABLE "report_scores" ADD CONSTRAINT "rs_gate_completeness" CHECK (CASE WHEN "report_scores"."product_passed" THEN length(btrim(coalesce("report_scores"."overview_sentence", ''))) > 0 AND "report_scores"."product_ease" IS NOT NULL AND "report_scores"."product_hair_fire" IS NOT NULL AND "report_scores"."product_exclusivity" IS NOT NULL AND length(btrim(coalesce("report_scores"."product_ease_rationale", ''))) > 0 AND length(btrim(coalesce("report_scores"."product_hair_fire_rationale", ''))) > 0 AND length(btrim(coalesce("report_scores"."product_exclusivity_rationale", ''))) > 0 AND "report_scores"."liquidity_tier" IS NOT NULL AND length(btrim(coalesce("report_scores"."liquidity_justification", ''))) > 0 AND "report_scores"."liquidity_depth_2pct_usd" IS NOT NULL AND ("report_scores"."liquidity_top_pool_tvl_usd" IS NOT NULL OR "report_scores"."liquidity_no_dex_pool") AND "report_scores"."narrative_maturity" IS NOT NULL AND "report_scores"."narrative_smart_money" IS NOT NULL AND "report_scores"."narrative_hair_fire" IS NOT NULL AND "report_scores"."narrative_communication" IS NOT NULL AND "report_scores"."narrative_lineage" IS NOT NULL AND "report_scores"."narrative_mutation" IS NOT NULL AND "report_scores"."narrative_total" IS NOT NULL AND length(btrim(coalesce("report_scores"."narrative_maturity_rationale", ''))) > 0 AND length(btrim(coalesce("report_scores"."narrative_smart_money_rationale", ''))) > 0 AND length(btrim(coalesce("report_scores"."narrative_hair_fire_rationale", ''))) > 0 AND length(btrim(coalesce("report_scores"."narrative_communication_rationale", ''))) > 0 AND length(btrim(coalesce("report_scores"."narrative_lineage_rationale", ''))) > 0 AND length(btrim(coalesce("report_scores"."narrative_mutation_rationale", ''))) > 0 AND "report_scores"."team_weighted_score" IS NOT NULL AND ("report_scores"."accrual_assessed" OR length(btrim(coalesce("report_scores"."accrual_absent_reason", ''))) > 0) AND length(btrim(coalesce("report_scores"."accrual_rationale", ''))) > 0 AND (NOT "report_scores"."accrual_assessed" OR "report_scores"."accrual_gross_annual_flow_usd" IS NOT NULL) AND (NOT "report_scores"."accrual_assessed" OR "report_scores"."accrual_net_annual_flow_usd" IS NOT NULL) AND (NOT "report_scores"."accrual_assessed" OR "report_scores"."discovery_market_cap_usd" IS NOT NULL) AND (NOT "report_scores"."accrual_assessed" OR "report_scores"."discovery_premium_kind" IS NOT NULL) AND length(btrim(coalesce("report_scores"."risk_notes", ''))) > 0 AND "report_scores"."waived_citation_count" IS NOT NULL ELSE true END);